import{_ as a,o as n,c as r,a5 as t}from"./chunks/framework.a5no_H3L.js";const g=JSON.parse('{"title":"虚拟内存与内存保护","description":"PE 格式讲的是「文件」，这一章讲「运行」：程序被加载进内存后，内存如何布局、如何保护。理解这些，才能看懂调试器里的内存地址，解释为什么同一个程序每次运行的地址不一样。","frontmatter":{"type":"explanation","level":"intermediate"},"headers":[],"relativePath":"reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md","filePath":"reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md"}'),s={name:"reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md"};function i(l,e,d,c,o,p){return n(),r("div",null,[...e[0]||(e[0]=[t(`<h1 id="虚拟内存与内存保护" tabindex="-1" data-src-line="2" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md">虚拟内存与内存保护 <a class="header-anchor" href="#虚拟内存与内存保护" aria-label="Permalink to &quot;虚拟内存与内存保护&quot;">​</a></h1><p data-src-line="4" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md">PE 格式讲的是「文件」，这一章讲「运行」：程序被加载进内存后，内存如何布局、如何保护。理解这些，才能看懂调试器里的内存地址，解释为什么同一个程序每次运行的地址不一样。</p><h2 id="_1-虚拟内存-每个进程都有一套假地址" tabindex="-1" data-src-line="6" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md">1. 虚拟内存：每个进程都有一套假地址 <a class="header-anchor" href="#_1-虚拟内存-每个进程都有一套假地址" aria-label="Permalink to &quot;1. 虚拟内存：每个进程都有一套假地址&quot;">​</a></h2><p data-src-line="8" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md">每个 Windows 进程看到的内存，都是<strong>虚拟内存</strong>——一套属于它自己的、独立的地址空间。进程 A 和进程 B 可能都认为自己访问 <code>0x140000000</code>，但它们映射到的物理内存完全不同。</p><p data-src-line="10" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md">虚拟内存按<strong>页</strong>（page）管理，一页通常是 4 KB。进程不是一启动就占满整个地址空间，而是按需映射：只有真正用到的页才会对应到物理内存，其余地址要么未分配，要么保留但未提交。访问一个未映射的地址，会触发<strong>访问违例（access violation）</strong>——你在调试器里看到的崩溃，很多就源于此。</p><p data-src-line="12" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md">对逆向的意义：<strong>内存地址是「虚拟」的，你在调试器里看到的地址要放在「这个进程的地址空间」里去理解，不能直接拿去和文件偏移划等号。</strong></p><h2 id="_2-用户态与内核态的划分" tabindex="-1" data-src-line="14" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md">2. 用户态与内核态的划分 <a class="header-anchor" href="#_2-用户态与内核态的划分" aria-label="Permalink to &quot;2. 用户态与内核态的划分&quot;">​</a></h2><p data-src-line="16" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md">Windows x64 把 64 位地址空间劈成两半：</p><table tabindex="0"><thead data-src-line="18" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md"><tr data-src-line="18" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md"><th style="text-align:left;">范围</th><th style="text-align:left;">归属</th></tr></thead><tbody data-src-line="20" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md"><tr data-src-line="20" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md"><td style="text-align:left;"><code>0x00000000_00000000</code> ～ <code>0x00007FFF_FFFFFFFF</code></td><td style="text-align:left;">用户态，程序代码和数据在这里</td></tr><tr data-src-line="21" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md"><td style="text-align:left;"><code>0xFFFF8000_00000000</code> 及以上</td><td style="text-align:left;">内核态，系统内核和驱动在这里</td></tr></tbody></table><p data-src-line="23" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md">用户态程序不能直接访问内核态地址，系统调用（syscall）通过 <code>ntdll.dll</code> 转进内核。逆向用户态程序时，你关心的几乎都在用户态范围内；反汇编窗口里地址以 <code>0x00007FF...</code> 开头是常态，以 <code>0xFFFF...</code> 开头则说明进入了内核态相关代码（普通用户态分析很少遇到）。</p><h2 id="_3-一个进程的内存大致长什么样" tabindex="-1" data-src-line="25" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md">3. 一个进程的内存大致长什么样 <a class="header-anchor" href="#_3-一个进程的内存大致长什么样" aria-label="Permalink to &quot;3. 一个进程的内存大致长什么样&quot;">​</a></h2><p data-src-line="27" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md">把上面的概念落到一张图。一个典型的用户态进程，其内存（从低地址到高地址）大致是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>低地址</span></span>
<span class="line"><span>+--------------------------+</span></span>
<span class="line"><span>|  NULL 区（前 64KB 保留）  |  ← 防止空指针被误用</span></span>
<span class="line"><span>+--------------------------+</span></span>
<span class="line"><span>|  主模块 .exe 的映像        |  ← 代码、数据、导入表等按节区映射进来</span></span>
<span class="line"><span>+--------------------------+</span></span>
<span class="line"><span>|  各 DLL 的映像             |  ← ntdll.dll、kernel32.dll、user32.dll ...</span></span>
<span class="line"><span>+--------------------------+</span></span>
<span class="line"><span>|  堆（heap）               |  ← 动态分配，new/malloc 的内存在这</span></span>
<span class="line"><span>+--------------------------+</span></span>
<span class="line"><span>|  栈（stack）              |  ← 函数调用、局部变量，向下生长</span></span>
<span class="line"><span>+--------------------------+</span></span>
<span class="line"><span>|  共享内存 / 映射文件 等    |</span></span>
<span class="line"><span>+--------------------------+</span></span>
<span class="line"><span>高地址（用户态边界 0x7FFF_FFFFFFFF）</span></span></code></pre></div><p data-src-line="47" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md">几点值得注意：</p><ul data-src-line="49" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md"><li data-src-line="49" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md"><strong>映像区</strong>是 PE 文件「映射」进内存的结果，节区按 <code>SectionAlignment</code> 对齐，和文件里的布局不完全一样（对应 PE 加载过程的文件偏移与 RVA 区别）。</li><li data-src-line="50" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md"><strong>堆</strong>由堆管理器分配，多个分配之间不连续，地址无规律。</li><li data-src-line="51" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md"><strong>栈</strong>是固定上限的一块区域，向下生长；每个线程都有自己的栈。</li><li data-src-line="52" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md">栈和堆的<strong>增长方向相反</strong>，中间的空隙是未映射区。</li></ul><p data-src-line="54" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md">调试器里看内存地址时，先判断它落在哪个区：<code>0x1400...</code> 开头多半是主模块，<code>0x00007FF...</code> 开头多半是某个系统 DLL，一个很小的地址可能是空指针或栈上的局部变量。</p><h2 id="_4-内存保护与安全缓解机制" tabindex="-1" data-src-line="56" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md">4. 内存保护与安全缓解机制 <a class="header-anchor" href="#_4-内存保护与安全缓解机制" aria-label="Permalink to &quot;4. 内存保护与安全缓解机制&quot;">​</a></h2><p data-src-line="58" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md">Windows 给进程内存页施加权限（读 / 写 / 执行），这也是 PE 节区权限在内存里的体现。同时还有几项安全缓解机制，直接影响你的分析体验：</p><table tabindex="0"><thead data-src-line="60" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md"><tr data-src-line="60" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md"><th style="text-align:left;">机制</th><th style="text-align:left;">作用</th><th style="text-align:left;">对分析的影响</th></tr></thead><tbody data-src-line="62" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md"><tr data-src-line="62" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md"><td style="text-align:left;">ASLR</td><td style="text-align:left;">随机化模块、堆、栈的基址</td><td style="text-align:left;">绝对地址每次运行都变，必须用「基址 + 偏移」定位</td></tr><tr data-src-line="63" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md"><td style="text-align:left;">DEP（数据执行保护）</td><td style="text-align:left;">数据页不可执行，防止栈/堆上执行代码</td><td style="text-align:left;">直接往栈上写 shellcode 并跳转会被拦截</td></tr><tr data-src-line="64" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md"><td style="text-align:left;">CFG（控制流保护）</td><td style="text-align:left;">限制间接调用的目标</td><td style="text-align:left;">部分异常跳转/ROP 手法被阻断</td></tr></tbody></table><p data-src-line="66" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md">这些机制的存在，意味着<strong>现代 Windows 逆向不能套用十几年前的老教程里「栈上执行代码」那套做法</strong>。<a href="./../07-packing/chapter-03-virtualization-anti-debugging.html">反调试与反静态分析</a>讲对抗时会回到这些机制上。</p><hr><blockquote data-src-line="70" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md"><p data-src-line="70" data-src-file="reverse-engineering/03-windows-internals/chapter-02-virtual-memory.md">本章建立的是运行时内存的图景：虚拟地址空间分用户态和内核态，内存按页管理和保护，ASLR、DEP、CFG 改变了现代逆向的玩法。下一章看进程的另一个维度——<a href="./chapter-01-process-thread.html">进程与线程</a>。</p></blockquote>`,22)])])}const h=a(s,[["render",i]]);export{g as __pageData,h as default};
